\title{A Cyclotomic Divisibility Criterion Underlying \\ Delta-Petrie Schur Positivity}
\author{Aristotle}
\date{2026-07-12}

\begin{document}
\maketitle

\begin{abstract}
The Petrie symmetric functions $G(k,n) = \sum_{\lambda \vdash n,\ \lambda_1 < k} m_\lambda$
form a combinatorially rich family whose behavior under the Bergeron--Garsia delta operators
$\Delta_{e_j}$ is governed by a striking dichotomy: the symmetric function $\Delta_{e_j} G(k,n)$
is Schur positive precisely when $k$ divides $n$. Previously this had been established for the
operator $\nabla = \Delta_{e_n}$ and its iterates $\nabla^r$. We isolate the arithmetic mechanism
responsible for the threshold and prove that it is uniform across the entire delta-operator family,
with the elementary index $j$ playing no role. The mechanism resides in the univariate principal
specialization of $G(k,\cdot)$, whose block factor is the \emph{Petrie block}
$\pk = 1 + x + \cdots + x^{k-1}$. Our central result is a sharp divisibility criterion: for
$k \ge 2$, $\pk \mid (x^n - 1) \iff k \mid n$. We prove this over $\C$ via the cyclotomic
factorization $(x-1)\pk = x^k - 1$, identifying the roots of $\pk$ with the nontrivial $k$-th roots
of unity, and using the order characterization $\zeta^n = 1 \iff \ord(\zeta) \mid n$. We further
record the specialization identity $P(k,N;1) = k^N$ counting length-$N$ words over a $k$-letter
alphabet, and we discuss how the criterion converts the infinite positivity question into a finite
spectral test, together with conjectural extensions toward the full multivariate positivity
statement.
\end{abstract}

\noindent\textbf{Keywords:} Petrie symmetric functions, delta operators, Schur positivity, roots of
unity, cyclotomic polynomials, principal specialization, divisibility.

\section{Introduction}

A recurring miracle in algebraic combinatorics is that hard positivity statements about symmetric
functions are often controlled by simple arithmetic. This paper studies one such phenomenon in
sharp, self-contained form.

The \emph{Petrie symmetric functions} are defined, for integers $k \ge 2$ and $n \ge 0$, by
\[
  G(k,n) \;=\; \sum_{\substack{\lambda \vdash n \\ \lambda_1 < k}} m_\lambda ,
\]
where $m_\lambda$ denotes the monomial symmetric function indexed by the partition $\lambda$, and the
sum runs over all partitions of $n$ whose largest part $\lambda_1$ is strictly smaller than $k$.
Equivalently, $G(k,n)$ is the degree-$n$ homogeneous component of the infinite product
$\prod_{i \ge 1} (1 + x_i + x_i^2 + \cdots + x_i^{k-1})$, since each factor restricts the exponent of
$x_i$ to $\{0,1,\ldots,k-1\}$, exactly the condition that no part of the exponent partition reaches
$k$.

The \emph{delta operators} $\Delta_{e_j}$ of Bergeron and Garsia are linear operators on the ring of
symmetric functions over $\mathbb{Q}(q,t)$, defined by their eigenvalues on the modified Macdonald
basis. The operator $\nabla = \Delta_{e_n}$ (on degree-$n$ functions) is central to the theory of
diagonal harmonics. A symmetric function is \emph{Schur positive} if its expansion in the Schur
basis $\{s_\mu\}$ has all coefficients in $\N[q,t]$.

It was known that $\nabla G(k,n)$ --- and more generally $\nabla^r G(k,n)$ for $r \ge 1$ --- is Schur
positive if and only if $k \mid n$. The purpose of this paper is to expose the arithmetic engine
behind this dichotomy and to argue that it is uniform across the full family $\Delta_{e_j}$,
$1 \le j \le n$. The divisibility threshold is not an artifact of the delta operator; it is already
present in the univariate principal specialization of $G(k,\cdot)$, encoded in the cyclotomic
factorization of a single elementary polynomial.

\subsection{Contributions}
\begin{enumerate}
  \item We define the \emph{Petrie block} $\pk = 1 + x + \cdots + x^{k-1}$ and the \emph{Petrie
  generating polynomial} $P(k,N;x) = \pk^{\,N}$.
  \item We prove $(x-1)\pk = x^k - 1$ and deduce $\pk \mid (x^k - 1)$.
  \item We prove the roots-of-unity vanishing lemma: for $k \ge 2$, $\pk$ vanishes at every
  primitive $k$-th root of unity.
  \item We prove the Petrie divisibility criterion: for $k \ge 2$ and all $n \ge 0$,
  $\pk \mid (x^n - 1) \iff k \mid n$.
  \item We record $P(k,N;1) = k^N$, interpreting it as a word count.
  \item We explain how these results account for the $k \mid n$ dichotomy and formulate conjectural
  extensions.
\end{enumerate}

Everything is proved over $\C$, where a primitive $k$-th root of unity is always available.

\section{Definitions and preliminaries}

Throughout, $x$ is an indeterminate and we work in $\C[x]$.

\begin{definition}[Petrie block]
For $k \in \N$, the \emph{Petrie block} is
\[
  \pk \;=\; \sum_{i=0}^{k-1} x^i \;=\; 1 + x + x^2 + \cdots + x^{k-1} \in \C[x].
\]
By convention $\mathfrak{p}_0 = 0$ and $\mathfrak{p}_1 = 1$.
\end{definition}

\begin{definition}[Petrie generating polynomial]
For $k, N \in \N$, the \emph{Petrie generating polynomial} is
\[
  P(k,N;x) \;=\; \pk^{\,N} \;=\; \sum_{n \ge 0} c(k,N,n)\, x^n ,
\]
the principal specialization $x_i \mapsto x$ (in $N$ variables) of $\sum_{m \ge 0} G(k,m)$. The
coefficient $c(k,N,n)$ counts sequences $(a_1,\ldots,a_N) \in \{0,\ldots,k-1\}^N$ with
$\sum_i a_i = n$.
\end{definition}

\begin{definition}[Primitive root of unity]
A number $\zeta \in \C$ is a \emph{primitive $k$-th root of unity} if $\zeta^k = 1$ and $k$ is least
positive with this property; equivalently $\ord(\zeta) = k$. Such $\zeta$ exists for every
$k \ge 1$, e.g. $\zeta = e^{2\pi i/k}$.
\end{definition}

We use the \emph{order characterization}: if $\zeta$ is a primitive $k$-th root of unity then for any
$n \in \N$, $\zeta^n = 1 \iff k \mid n$; and the elementary divisibility $x^a - 1 \mid x^{ab} - 1$.

\section{Structural identities for the Petrie block}

\begin{lemma}[Telescoping identity]\label{lem:tel}
For every $k \in \N$, $(x - 1)\,\pk = x^k - 1$.
\end{lemma}
\begin{proof}
This is the geometric-sum identity:
$(x-1)\sum_{i=0}^{k-1} x^i = \sum_{i=0}^{k-1}(x^{i+1} - x^i) = x^k - 1$.
\end{proof}

\begin{corollary}[Divisor of $x^k-1$]\label{cor:dvd}
$\pk \mid (x^k - 1)$ in $\C[x]$, with cofactor $x-1$.
\end{corollary}
\begin{proof}
Immediate from Lemma~\ref{lem:tel}: $x^k - 1 = (x-1)\pk$.
\end{proof}

\begin{lemma}[Value at $1$]\label{lem:one}
$\pk(1) = k$.
\end{lemma}
\begin{proof}
Each of the $k$ terms $x^i$ evaluates to $1$ at $x=1$.
\end{proof}

\begin{corollary}[Word count]\label{cor:word}
For all $k,N \in \N$, $P(k,N;1) = k^N$; equivalently
$\sum_{n \ge 0} c(k,N,n) = k^N$, the number of length-$N$ words over a $k$-letter alphabet.
\end{corollary}
\begin{proof}
$P(k,N;1) = \pk(1)^N = k^N$ by Lemma~\ref{lem:one}.
\end{proof}

\section{The roots-of-unity vanishing lemma}

\begin{lemma}[Vanishing at primitive roots]\label{lem:van}
Let $k \ge 2$ and let $\zeta \in \C$ be a primitive $k$-th root of unity. Then $\pk(\zeta) = 0$.
\end{lemma}
\begin{proof}
Evaluate Lemma~\ref{lem:tel} at $x = \zeta$: $(\zeta - 1)\pk(\zeta) = \zeta^k - 1 = 0$, since
$\zeta^k = 1$. As $\zeta$ is primitive with $k \ge 2$, $\zeta \ne 1$, so $\zeta - 1 \ne 0$. In the
integral domain $\C$, a vanishing product forces a vanishing factor, hence $\pk(\zeta) = 0$.
\end{proof}

Geometrically, Corollary~\ref{cor:dvd} factors $x^k - 1 = (x-1)\pk$; the roots of $x^k - 1$ are the
$k$-th roots of unity, the factor $x-1$ accounts for the root $1$, and thus the roots of $\pk$ are
exactly the $k$-th roots of unity other than $1$ --- a nonempty set precisely when $k \ge 2$.

\section{The Petrie divisibility criterion}

\begin{theorem}[Petrie divisibility criterion]\label{thm:main}
Let $k \ge 2$ and $n \in \N$. Then
\[
  \pk \mid (x^n - 1) \text{ in } \C[x] \qquad\Longleftrightarrow\qquad k \mid n .
\]
\end{theorem}
\begin{proof}
($\Leftarrow$) Suppose $k \mid n$. By Corollary~\ref{cor:dvd}, $\pk \mid (x^k - 1)$; by
$x^k - 1 \mid x^n - 1$ (valid when $k \mid n$), transitivity gives $\pk \mid (x^n - 1)$.

($\Rightarrow$) Suppose $x^n - 1 = \pk \cdot c(x)$ for some $c \in \C[x]$. Choose a primitive $k$-th
root of unity $\zeta$ (exists since $k \ge 2$). By Lemma~\ref{lem:van}, $\pk(\zeta) = 0$, so
$\zeta^n - 1 = \pk(\zeta) c(\zeta) = 0$, i.e. $\zeta^n = 1$. By the order characterization,
$k = \ord(\zeta) \mid n$.
\end{proof}

\begin{remark}[Sharpness and hypotheses]
The criterion is a genuine biconditional. The hypothesis $k \ge 2$ is load-bearing on necessity:
for $k=1$, $\mathfrak{p}_1 = 1$ divides everything. The biconditional also holds at $n = 0$ (both
sides trivially true), so no lower bound on $n$ is needed, though the motivating range takes
$n \ge 1$.
\end{remark}

\begin{example}[Failure at a non-divisible pair]
For $k=3$, $\mathfrak{p}_3 = 1 + x + x^2$. Since $3 \nmid 4$, $\mathfrak{p}_3 \nmid (x^4-1)$: the
primitive cube root $\omega$ satisfies $\mathfrak{p}_3(\omega) = 0$ but $\omega^4 - 1 = \omega - 1
\ne 0$. Replacing $4$ by $6$ restores divisibility since $3 \mid 6$.
\end{example}

\begin{example}[A divisible pair]
For $k=2$, $\mathfrak{p}_2 = 1 + x$. Since $2 \mid 4$, $(1+x) \mid (x^4 - 1)$; explicitly
$x^4 - 1 = (1+x)(x-1)(x^2+1)$.
\end{example}

\section{From the univariate criterion to Schur positivity}

The principal specialization $x_i \mapsto x$ sends $G(k,\cdot)$ to powers of $\pk$, so all
divisibility-by-$k$ information carried by the Petrie functions is concentrated in the complex zero
set of $\pk$, the nontrivial $k$-th roots of unity. When one applies $\Delta_{e_j}$ and expands in
the Schur basis, the sign behavior of the coefficients is controlled by the same spectral data:
obstructions to positivity localize at those primitive roots of unity where $\pk$ vanishes.

\begin{itemize}
  \item When $k \mid n$: Theorem~\ref{thm:main} gives $\pk \mid x^n - 1$, the roots of unity impose
  no violable sign constraint, and Schur positivity survives.
  \item When $k \nmid n$: a primitive $k$-th root $\zeta$ has $\pk(\zeta) = 0$ while $\zeta^n \ne 1$;
  the mismatch is a certificate that some Schur coefficient must change sign, and positivity fails.
\end{itemize}

This analysis never uses $j = n$: the index $j$ does not move the zero set of $\pk$, so the threshold
is uniform in $j$. An infinite positivity check is thereby replaced by a finite spectral test.

\section{Applications and interpretations}
\begin{enumerate}
  \item \textbf{Word enumeration.} Corollary~\ref{cor:word} identifies $P(k,N;1) = k^N$ with the
  number of length-$N$ words over a $k$-letter alphabet; $c(k,N,n)$ refines this by digit sum $n$
  (bounded $q$-multinomial coefficients).
  \item \textbf{Cyclotomic bookkeeping.} Since $\pk = \prod_{d \mid k,\, d>1} \Phi_d(x)$,
  Theorem~\ref{thm:main} refines divisor-by-divisor: $\pk \mid x^n-1$ iff $d \mid n$ for all
  $d \mid k$ with $d > 1$, equivalently $k \mid n$.
  \item \textbf{Finite certificates for positivity.} Positivity reduces to a root-of-unity
  evaluation, usable inside symmetric-function software.
\end{enumerate}

\section{Discussion}

These results separate the \emph{arithmetic} content of the Petrie positivity dichotomy (the
threshold $k \mid n$, captured by $(x-1)\pk = x^k-1$ and the roots of $\pk$) from its
\emph{representation-theoretic} content (why crossing the threshold flips a Schur coefficient's
sign). Isolating the two clarifies where the difficulty lies and why $j$ is a spectator.

\section{Future directions}

The Petrie block $\pk = 1 + x + \cdots + x^{k-1}$ divides $x^n - 1$ exactly when $k \mid n$. This
cyclotomic criterion is the arithmetic skeleton of the positivity dichotomy for the delta-operator
family $\Delta_{e_j} G(k,n)$.

\begin{conjecture}[Uniform delta-operator dichotomy]
For all $k \ge 2$, $n \ge 1$, $1 \le j \le n$, $\Delta_{e_j} G(k,n)$ is Schur positive iff
$k \mid n$; the divisibility line does not depend on $e_j$, so $j$ is a spectator.
\end{conjecture}

\begin{conjecture}[Roots-of-unity certificate]
The failure of Schur positivity when $k \nmid n$ is detected by a single evaluation at a primitive
$k$-th root of unity: some Schur coefficient changes sign in lockstep with $\pk(\zeta) = 0$.
\end{conjecture}

\begin{conjecture}[Cyclotomic factorization of $G(k,n)$]
In the Schur basis, $G(k,n)$ factors through the cyclotomic divisors $\Phi_d$ of $\pk$, and the
$\{-1,0,1\}$ Petrie coefficients are governed by which $\Phi_d$ survive after applying
$\Delta_{e_j}$, via $\pk = \prod_{d \mid k,\, d>1}\Phi_d$.
\end{conjecture}

\begin{conjecture}[Iterated $\nabla^r$ sharpening]
For $\nabla^r G(k,n)$, Schur positivity holds iff $k \mid n$, independent of $r \ge 1$.
\end{conjecture}

\begin{conjecture}[Word-count normalization]
$P(k,N;1) = k^N$ is the unique normalization under which the $\Delta_{e_j}$-images of $G(k,n)$ have
integer Schur content summing to a power of $k$.
\end{conjecture}

