from typing import List

def petrie_block(k: int) -> List[int]:
    """Coefficients (low to high) of p_k = 1 + x + ... + x^{k-1}."""
    return [1] * k if k > 0 else [0]

def poly_mul(a: List[int], b: List[int]) -> List[int]:
    out = [0] * (len(a) + len(b) - 1)
    for i, ai in enumerate(a):
        for j, bj in enumerate(b):
            out[i + j] += ai * bj
    return out

def petrie_gf(k: int, N: int) -> List[int]:
    """Coefficients of P(k,N;x) = p_k(x)^N."""
    result: List[int] = [1]
    for _ in range(N):
        result = poly_mul(result, petrie_block(k))
    return result

if __name__ == "__main__":
    for k in range(2, 5):
        for N in range(1, 4):
            g = petrie_gf(k, N)
            print(f"k={k} N={N}: coeffs={g}, sum={sum(g)}, k^N={k**N}")
            assert sum(g) == k ** N

from fractions import Fraction
from typing import List, Tuple

def petrie_block(k: int) -> List[int]:
    return [1] * k

def x_pow_minus_one(n: int) -> List[int]:
    c = [0] * (n + 1)
    c[n], c[0] = 1, -1
    return c

def poly_divides(den: List[int], num: List[int]) -> bool:
    """Exact polynomial divisibility test over the rationals."""
    rem = [Fraction(c) for c in num]
    d = [Fraction(c) for c in den]
    dd = len(d) - 1
    for i in range(len(rem) - 1, dd - 1, -1):
        if rem[i] == 0:
            continue
        f = rem[i] / d[-1]
        for j in range(len(d)):
            rem[i - dd + j] -= f * d[j]
    return all(c == 0 for c in rem)

def criterion_holds(k: int, n: int) -> Tuple[bool, bool]:
    """Return (polynomial divisibility, arithmetic k|n) — they must agree."""
    return poly_divides(petrie_block(k), x_pow_minus_one(n)), (n % k == 0)

if __name__ == "__main__":
    for k in range(2, 7):
        for n in range(1, 16):
            poly, arith = criterion_holds(k, n)
            assert poly == arith, (k, n)
    print("p_k | (x^n - 1)  <=>  k | n  verified for k in 2..6, n in 1..15")

import cmath
from typing import List

def petrie_block(k: int) -> List[int]:
    return [1] * k

def eval_complex(p: List[int], z: complex) -> complex:
    acc = 0j
    for c in reversed(p):
        acc = acc * z + c
    return acc

def spectral_verdict(k: int, n: int, tol: float = 1e-9) -> str:
    """Use a primitive k-th root of unity as a positivity/divisibility certificate."""
    zeta = cmath.exp(2j * cmath.pi / k)
    assert abs(eval_complex(petrie_block(k), zeta)) < tol  # block vanishes
    return "k | n  (no obstruction)" if abs(zeta ** n - 1) < tol else "k does not divide n  (obstruction)"

if __name__ == "__main__":
    for k in (3, 4, 5):
        for n in (4, 6, 10, 12):
            print(f"k={k}, n={n}: {spectral_verdict(k, n)}")

